\begin{aligned}
T[a x_1(t)+b x_2(t)] &= 4[a x_1(t)+b x_2(t)] \\
&= a[4x_1(t)] + b[4x_2(t)] \\
&= aT[x_1(t)]+bT[x_2(t)]
\end{aligned}

\begin{aligned}
T[a x_1(t)+b x_2(t)] &= \frac{d}{dt}[a x_1(t)+b x_2(t)] \\
&= a\frac{d}{dt}x_1(t)+b\frac{d}{dt}x_2(t) \\
&= aT[x_1(t)]+bT[x_2(t)]
\end{aligned}

\begin{aligned}
T[a x_1(t)+b x_2(t)] &= t[a x_1(t)+b x_2(t)] \\
&= a[t x_1(t)]+b[t x_2(t)] \\
&= aT[x_1(t)]+bT[x_2(t)]
\end{aligned}
